import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 9

    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    try:
        csv.field_size_limit(2147483647)
    except (OverflowError, csv.Error):
        pass

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        skipinitialspace=False,
        strict=False,
    )

    records = []
    try:
        for row in reader:
            if row:
                records.append([str(value) for value in row])
    except csv.Error:
        return {"columns": [], "rows": []}

    if not records:
        return {"columns": [], "rows": []}

    date_re = re.compile(r"^\s*\d{1,4}([/\-.])\d{1,2}\1\d{1,4}\s*$")
    time_re = re.compile(r"^\s*\d{1,2}:\d{2}(?::\d{2})?\s*$")
    number_re = re.compile(
        r"^\s*[$€£¥]?\s*[+-]?(?:\d+(?:,\d{3})*|\d*)(?:\.\d+)?%?\s*$"
    )
    url_re = re.compile(r"^\s*[a-zA-Z][a-zA-Z0-9+.-]*://")

    def header_likeness(row):
        score = 0.0
        seen = set()
        for value in row:
            text = value.strip()
            if not text:
                score -= 0.25
                continue

            folded = text.casefold()
            if folded in seen:
                score -= 0.5
            else:
                seen.add(folded)

            if url_re.match(text):
                score -= 2.5
            elif date_re.match(text) or time_re.match(text) or number_re.match(text):
                score -= 2.0
            elif re.search(r"[A-Za-z]", text):
                score += 1.0
            else:
                score -= 0.5

            if "\n" in text or "\r" in text:
                score -= 0.75
            if len(text) > 80:
                score -= 0.75
        return score

    candidates = []
    search_limit = min(len(records), 50)

    for index in range(search_limit):
        row = records[index]
        if len(row) != expected_width:
            continue

        current_score = header_likeness(row)
        following = records[index + 1:index + 7]
        width_matches = sum(len(item) == expected_width for item in following)

        following_scores = [
            header_likeness(item)
            for item in following
            if len(item) == expected_width
        ]
        contrast = 0.0
        if following_scores:
            contrast = current_score - (
                sum(following_scores) / len(following_scores)
            )

        score = current_score + width_matches * 0.75 + contrast * 0.6
        candidates.append((score, -index, index))

    if candidates:
        header_index = max(candidates)[2]
    else:
        header_index = 0

    header = list(records[header_index])

    if len(header) < expected_width:
        header.extend("" for _ in range(expected_width - len(header)))
    elif len(header) > expected_width:
        header = header[:expected_width - 1] + [
            ",".join(header[expected_width - 1:])
        ]

    columns = []
    used = {}
    for position, value in enumerate(header):
        name = value
        if not name:
            name = "column_" + str(position + 1)

        key = name.casefold()
        count = used.get(key, 0) + 1
        used[key] = count
        if count > 1:
            name = name + "_" + str(count)

        columns.append(name)

    rows = []
    for row in records[header_index + 1:]:
        normalized = list(row)

        if len(normalized) < expected_width:
            normalized.extend("" for _ in range(expected_width - len(normalized)))
        elif len(normalized) > expected_width:
            normalized = normalized[:expected_width - 1] + [
                ",".join(normalized[expected_width - 1:])
            ]

        rows.append([str(value) for value in normalized])

    return {"columns": columns, "rows": rows}
